<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {ElButton,ElInput,ElInputNumber,ElSelect,ElOption} from 'element-plus'
import {api} from '../../api'
import StoreSelector from './StoreSelector.vue'
import FenInput from './FenInput.vue'
import ShippingTargets from './ShippingTargets.vue'
import StoreLocationPicker from '../../shared/maps/StoreLocationPicker.vue'
import {money,type Point,type Target} from './types'
const props=defineProps<{storeId:string|null;city?:string;mode:'DELIVERY'|'EXPRESS'}>()
const selectedStores=ref<string[]>([]),trialStoreId=computed(()=>props.storeId||selectedStores.value[0]||null)
const targets=ref<Target[]>([]),skuId=ref(''),quantity=ref(1),goodsFen=ref(6800),coupon=ref(0),point=ref<Point|null>(null),province=ref(''),city=ref(''),district=ref(''),busy=ref(false),error=ref('')
interface Result {eligible:boolean;pending:boolean;message:string;costFen:number;customerFeeFen:number;warehouseBearsFen:number;platformBearsFen:number;freeSource:string;distanceMeters:number|null}
const result=ref<Result|null>(null),skus=computed(()=>targets.value.flatMap(p=>p.skus.map(s=>({...s,label:`${p.productName} · ${s.specLabel||s.skuCode}`}))));let epoch=0
function receive(items:Target[]){targets.value=[...targets.value.filter(p=>!items.some(t=>t.productId===p.productId)),...items]}
async function trial(){if(!skuId.value||!trialStoreId.value||busy.value)return;const current=++epoch;busy.value=true;result.value=null;error.value='';try{const r=await api<Result>('/shipping/trial',{method:'POST',body:JSON.stringify({storeId:trialStoreId.value,deliveryMode:props.mode,goodsFen:goodsFen.value,couponDiscountFen:coupon.value,items:[{skuId:skuId.value,quantity:quantity.value}],address:{province:province.value,city:city.value,district:district.value,...(point.value||{latitude:null,longitude:null})}})});if(current===epoch)result.value=r}catch(e){if(current===epoch)error.value=e instanceof Error?e.message:'试算失败，请重试。'}finally{if(current===epoch)busy.value=false}}
watch(()=>[trialStoreId.value,skuId.value,quantity.value,goodsFen.value,coupon.value,province.value,city.value,district.value,point.value],()=>{epoch++;result.value=null;busy.value=false})
onBeforeUnmount(()=>epoch++)
</script>
<template><section><p>试算采用当前服务端配置，不创建订单。门槛按商品金额扣除优惠券后的金额判断。</p><StoreSelector v-if="!storeId" v-model="selectedStores" :multiple="false" label="试算前置仓" :disabled="busy"/><ShippingTargets catalog-only :model-value="[]" :disabled="busy" @targets="receive"/><div class="rule-fields"><label>试算规格<ElSelect v-model="skuId" filterable aria-label="试算规格" :disabled="busy"><ElOption v-for="s in skus" :key="s.skuId" :label="s.label" :value="s.skuId"/></ElSelect></label><label>商品数量<ElInputNumber v-model="quantity" :min="1" :max="9999" :precision="0" :disabled="busy"/></label><FenInput v-model="goodsFen" label="商品金额" :disabled="busy"/><FenInput v-model="coupon" label="优惠券优惠" :disabled="busy"/><template v-if="mode==='EXPRESS'"><label>收货省份<ElInput v-model="province" aria-label="收货省份" placeholder="行政区全称，例如广东省" :disabled="busy"/></label><label>收货城市<ElInput v-model="city" aria-label="收货城市" placeholder="例如深圳市" :disabled="busy"/></label><label>收货区县<ElInput v-model="district" aria-label="收货区县" placeholder="例如盐田区" :disabled="busy"/></label></template></div><StoreLocationPicker v-if="mode==='DELIVERY'" :city="props.city||''" entity-label="收货地址" :latitude="point?.latitude??null" :longitude="point?.longitude??null" :context-key="`${storeId}:trial`" :disabled="busy" @select="item=>{point={latitude:item.latitude,longitude:item.longitude};result=null}"/><p v-if="error" role="alert" class="error">{{error}}</p><div v-if="result" class="trial-result" role="status"><strong>{{result.eligible?'可以配送':result.pending?'地址待确认':'不可配送'}}</strong><p v-if="result.message">{{result.message}}</p><template v-if="result.eligible"><p>用户运费 {{money(result.customerFeeFen)}} · 配送成本 {{money(result.costFen)}}</p><p>前置仓承担 {{money(result.warehouseBearsFen)}} · 平台承担 {{money(result.platformBearsFen)}}</p><p>包邮来源：{{({NONE:'无包邮',WAREHOUSE:'经营包邮',PLATFORM:'平台活动',MIXED:'按商品模板分别判断'} as Record<string,string>)[result.freeSource]||result.freeSource}}<span v-if="result.distanceMeters!==null"> · 配送距离 {{result.distanceMeters}} 米</span></p></template></div><ElButton type="primary" :loading="busy" :disabled="!trialStoreId||!skuId||mode==='DELIVERY'&&!point||mode==='EXPRESS'&&!province" @click="trial">试算运费</ElButton></section></template>
